ZWVuLmt0UEsBAhQDFAAAAAgAgKJSXUoCHLyhBwAA5R4AAFcAAAAAAAAAAAAAAICBi/EDAGFycXVpdm9zL2FwcC9zcmMvbWFpbi9qYXZhL2JyL2NvbS9mbGF2
aW90b3JyZXMvaXB0dnByZW1pdW0vdWkvc2VyaWVzL1Nlcmllc1ZpZXdNb2RlbC5rdFBLAQIUAxQAAAAIAIQMU103OH46Al0AAHTsAAANAAAAAAAAAAAAAACA
gaH5AwBtYW5pZmVzdC5qc29uUEsFBgAAAAA2ADYAVBwAAM5WBAAAAA==
'@
[System.IO.File]::WriteAllBytes($archive, [Convert]::FromBase64String($payload))
if ((Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'eaaa3a13ce107a3e243aee664733f557b8bcee8bcd8df3188dd6f5bfbe30527b') { throw 'Pacote incorreto. Nada foi aplicado.' }
Expand-Archive -LiteralPath $archive -DestinationPath $temp
# Prepare only the two version properties; all other local bytes are preserved.
$localFile = Join-Path $Projeto 'local.properties'
if (-not (Test-Path -LiteralPath $localFile -PathType Leaf)) { throw 'local.properties nao encontrado. Execute na raiz Android correta.' }
$localEncoding = [System.Text.Encoding]::GetEncoding(28591)
$localBytes = [System.IO.File]::ReadAllBytes($localFile)
$localText = $localEncoding.GetString($localBytes)
$codePattern = '(?m)^[ \t]*APP_VERSION_CODE(?:[ \t]*[=:][ \t]*|[ \t]+)([^\r\n]*)'
$namePattern = '(?m)^[ \t]*APP_VERSION_NAME(?:[ \t]*[=:][ \t]*|[ \t]+)([^\r\n]*)'
$codes = [regex]::Matches($localText, $codePattern)
$currentCode = 2L
if ($codes.Count -gt 0) {
    $number = $codes[$codes.Count - 1].Groups[1].Value.Trim()
    if ($number -notmatch '^\d+$' -or -not [long]::TryParse($number, [ref]$currentCode) -or $currentCode -lt 2 -or $currentCode -gt 2100000000) { throw 'APP_VERSION_CODE invalido em local.properties. Nada foi alterado.' }
}
$names = [regex]::Matches($localText, $namePattern)
if ($currentCode -gt 9) { throw 'O projeto ja tem numero interno maior que 9. Nada foi alterado; envie a versao atual.' }
$targetCode = 9L
$targetName = '1.07'
if ([string]::IsNullOrWhiteSpace($targetName) -or $targetName.Length -gt 40) { throw 'APP_VERSION_NAME invalido. Nada foi alterado.' }
$updatedLocal = $localText
# Only version assignments change; unknown properties keep their original bytes.
$codeLine = 'APP_VERSION_CODE=' + $targetCode
$nameLine = 'APP_VERSION_NAME=' + $targetName
if ($codes.Count -gt 0) { $updatedLocal = [regex]::Replace($updatedLocal, $codePattern, [System.Text.RegularExpressions.MatchEvaluator]{param($match) $codeLine}) }
else { $updatedLocal += "`r`n" + $codeLine + "`r`n" }
if ($names.Count -gt 0) { $updatedLocal = [regex]::Replace($updatedLocal, $namePattern, [System.Text.RegularExpressions.MatchEvaluator]{param($match) $nameLine}) }
else { $updatedLocal += "`r`n" + $nameLine + "`r`n" }

$executor = (Get-Process -Id $PID).Path
if ($Verificar) {
    & $executor -NoProfile -ExecutionPolicy Bypass -File (Join-Path $temp 'Aplicar.ps1') -Projeto $Projeto -Verificar
    if ($LASTEXITCODE -ne 0) { throw 'Verificacao dos fontes falhou. Nada foi alterado ou publicado.' }
    exit 0
}
& $executor -NoProfile -ExecutionPolicy Bypass -File (Join-Path $temp 'Aplicar.ps1') -Projeto $Projeto
if ($LASTEXITCODE -ne 0) { throw 'Aplicacao interrompida. Envie a mensagem do instalador.' }
if ($updatedLocal -cne $localText) {
    $backup = Join-Path $Projeto ('.iptv-backups/versao-app-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
    New-Item -ItemType Directory -Path $backup -Force | Out-Null
    [System.IO.File]::WriteAllBytes((Join-Path $backup 'local.properties'), $localBytes)
    $temporary = Join-Path $Projeto ('local.properties.' + [guid]::NewGuid().ToString('N') + '.tmp')
    try {
        [System.IO.File]::WriteAllBytes($temporary, $localEncoding.GetBytes($updatedLocal))
        [System.IO.File]::Replace($temporary, $localFile, (Join-Path $backup 'local.properties'))
    } finally { if (Test-Path -LiteralPath $temporary) { Remove-Item -LiteralPath $temporary -Force } }
}
Write-Host ('Versao preparada: ' + $targetName + ' | numero interno: ' + $targetCode)

if (-not $NaoCompilar) {
    $javaCandidates = @($env:JAVA_HOME)
    if ($env:ProgramFiles) { $javaCandidates += (Join-Path $env:ProgramFiles 'Android/Android Studio/jbr') }
    if ($env:LOCALAPPDATA) { $javaCandidates += (Join-Path $env:LOCALAPPDATA 'Programs/Android Studio/jbr') }
    $javaFound = $false
    foreach ($candidate in $javaCandidates) {
        if ($candidate -and (Test-Path -LiteralPath (Join-Path $candidate 'bin/java.exe') -PathType Leaf)) {
            $env:JAVA_HOME = $candidate
            $env:Path = (Join-Path $candidate 'bin') + [System.IO.Path]::PathSeparator + $env:Path
            $javaFound = $true
            break
        }
    }
    if (-not $javaFound -and -not (Get-Command java -ErrorAction SilentlyContinue)) { throw 'Java nao encontrado. Informe o JAVA_HOME do Android Studio e execute este mesmo script novamente; o pacote ja aplicado sera reconhecido.' }
    Push-Location $Projeto
    try {
        $buildTasks = @('assembleDebug', '-PiptvDebugPauseSharedLibrary=false')
        if ($TestarApresentacao -or $TestarSeries -or $TestarLista -or $TestarFluidez) { $buildTasks += 'assembleDebugAndroidTest' }
        & (Join-Path $Projeto 'gradlew.bat') @buildTasks
        if ($LASTEXITCODE -ne 0) { throw 'Compilacao falhou. Envie o erro.' }
        $apkFolder = Join-Path $Projeto 'app/build/outputs/apk/debug'
        $outputs = Get-IptvDebugApks -Folder $apkFolder -VersionCode 9 -VersionName '1.07'
        Write-Host ('Conferido: ' + $outputs.Entries.Count + ' APK(s), versao 1.07, numero interno 9.')
        if (-not $outputs.FullSet) { Write-Host 'Compilacao direcionada a processador: o APK compativel sera usado no emulador.' }
        if ($TestarApresentacao -or $TestarSeries -or $TestarLista -or $TestarFluidez) {
            $adb = $null
            $adbCommand = Get-Command adb -ErrorAction SilentlyContinue
            if ($adbCommand) { $adb = $adbCommand.Source }
            foreach ($sdkRoot in @($env:ANDROID_HOME, $env:ANDROID_SDK_ROOT, (Join-Path $env:LOCALAPPDATA 'Android/Sdk'))) {
                if ($sdkRoot -and (Test-Path -LiteralPath (Join-Path $sdkRoot 'platform-tools/adb.exe'))) {
                    $adb = Join-Path $sdkRoot 'platform-tools/adb.exe'
                    break
                }
            }
            if (-not $adb) { throw 'ADB nao encontrado. Os fontes e APKs estao preparados; informe o SDK e repita.' }
            & $adb -s $Emulador get-state
            if ($LASTEXITCODE -ne 0) { throw 'Emulador nao conectado. Abra-o no Android Studio e repita este script com os testes solicitados.' }
            $deviceAbis = ((& $adb -s $Emulador shell getprop ro.product.cpu.abilist | Out-String).Trim()) -split ','
            if ($LASTEXITCODE -ne 0 -or -not ($deviceAbis -join '').Trim()) {
                $deviceAbis = @((& $adb -s $Emulador shell getprop ro.product.cpu.abi | Out-String).Trim())
            }
            $installApk = Select-IptvEmulatorApk -Outputs $outputs -Abis $deviceAbis
            Write-Host ('Instalando por cima: ' + [System.IO.Path]::GetFileName($installApk))
            & $adb -s $Emulador install -r $installApk
            if ($LASTEXITCODE -ne 0) { throw 'Falha ao instalar por cima. Nao desinstale nem limpe dados; envie o erro.' }
            & $adb -s $Emulador install -r (Join-Path $Projeto 'app/build/outputs/apk/androidTest/debug/app-debug-androidTest.apk')
            if ($LASTEXITCODE -ne 0) { throw 'Falha ao instalar o APK de testes. Envie o erro.' }
            if ($CapturarLog) {
                $capturaDesde = (& $adb -s $Emulador shell "date '+%m-%d %H:%M:%S.000'" | Out-String).Trim()
                if ($capturaDesde -notmatch '^\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.000$') { $capturaDesde = '2000' }
            }
            $suites = @()
            if ($TestarApresentacao) { $suites += @{ Classe = 'SeriesPresentationDeviceTest'; Arquivo = 'diagnostico-apresentacao-emulador.txt'; Quantidade = 3 } }
            if ($TestarSeries) { $suites += @{ Classe = 'SeriesLoadingDeviceTest'; Arquivo = 'diagnostico-series-emulador.txt'; Quantidade = 3 } }
            if ($TestarLista) { $suites += @{ Classe = 'SeriesProviderDeviceTest'; Arquivo = 'diagnostico-lista-emulador.txt'; Quantidade = 1 } }
            if ($TestarFluidez) { $suites += @{ Classe = 'CatalogNavigationDeviceTest'; Arquivo = 'diagnostico-fluidez-emulador.txt'; Quantidade = 9 } }
            foreach ($suite in $suites) {
                $diagnostico = Join-Path $Projeto $suite.Arquivo
                $classe = 'br.com.flaviotorres.iptvpremium.data.repository.' + $suite.Classe
                $previousErrorAction = $ErrorActionPreference
                try {
                    $ErrorActionPreference = 'Continue'
                    $resultado = & $adb -s $Emulador shell am instrument -w -r -e class $classe br.com.flaviotorres.iptvpremium.test/androidx.test.runner.AndroidJUnitRunner 2>&1
                    $adbExit = $LASTEXITCODE
                } finally { $ErrorActionPreference = $previousErrorAction }
                $textoResultado = ($resultado | Out-String)
                $textoResultado | Set-Content -LiteralPath $diagnostico -Encoding UTF8
                Write-Host $textoResultado
                if ($adbExit -ne 0 -or $textoResultado -notmatch ('OK \(' + $suite.Quantidade + ' tests?\)') -or $textoResultado -match 'FAILURES!!!|INSTRUMENTATION_FAILED|Process crashed') {
                    if ($CapturarLog) { Write-Warning ('Teste falhou; diagnostico salvo em: ' + $diagnostico) }
                    else { throw ('Teste nativo nao passou. Envie o arquivo: ' + $diagnostico) }
                } else {
                    Write-Host ('PASS: ' + $suite.Classe + '. Confira tambem a navegacao e a memoria reais na TV.')
                }
            }
        }
        if (-not $CapturarLog) { Invoke-Item $apkFolder }
    } finally { Pop-Location }
}
Write-Host 'Layout, busca e foco preparados. Confira navegacao rapida, titulos longos e consumo total na TV.'

if ($CapturarLog) {
    $logArquivo = Join-Path $Projeto 'diagnostico-fluidez-memoria-logcat.txt'
    Write-Host 'Teste no emulador: trocar categorias, digitar rapidamente, manter a terceira coluna e reproduzir video. CatalogMemory mostra PSS e pico; alvo total 350 MB.'
    Write-Host ('Coleta salva em: ' + $logArquivo + '. Use Ctrl+C para encerrar.')
    & $adb -s $Emulador shell am start -n br.com.flaviotorres.iptvpremium/.MainActivity
    if ($LASTEXITCODE -ne 0) { Write-Warning 'Abra o aplicativo manualmente no emulador.' }
    & $adb -s $Emulador logcat -T $capturaDesde -v brief 'StartupPerf:I' 'StartupPerf:I' 'StartupPerf:I' 'CatalogMemory:D' 'SharedLibrary:D' 'SeriesDetails:D' 'PlaylistConnection:D' 'SeriesDetailsTmdb:D' 'SeriesArtwork:D' 'MovieDetailsPerf:I' 'MovieDetailsPreload:I' 'TmdbEnrichment:D' 'XtreamCatalogParser:I' 'XtreamEndpointPerf:I' '*:S' | Tee-Object -FilePath $logArquivo
}
